/// The 391 standard strings, SID 0 to 390 (Adobe TN 5176, Appendix A).
pub fn cff_strings() -> &'static [&'static str] {
    static NAMES: std::sync::OnceLock<Vec<&'static str>> = std::sync::OnceLock::new();
    NAMES.get_or_init(|| CFF_STRINGS_TEXT.split(' ').collect())
}

