/// The 258 glyph names an index of 'post' format 1 and 2 refers to.
pub fn mac_glyphs() -> &'static [&'static str] {
    static NAMES: std::sync::OnceLock<Vec<&'static str>> = std::sync::OnceLock::new();
    NAMES.get_or_init(|| MAC_GLYPHS_TEXT.split(' ').collect())
}

fn standard_sids() -> [usize; 256] {
    let mut sids = [0usize; 256];
    let mut range = |from: usize, to: usize, sid: usize| {
        for (i, slot) in sids[from..=to].iter_mut().enumerate() {
            *slot = sid + i;
        }
    };
    range(32, 126, 1);
    range(161, 175, 96);
    range(177, 180, 111);
    range(182, 189, 115);
    range(191, 191, 123);
    range(193, 200, 124);
    range(202, 203, 132);
    range(205, 208, 134);
    range(225, 225, 138);
    range(227, 227, 139);
    range(232, 235, 140);
    range(241, 241, 144);
    range(245, 245, 145);
    range(248, 251, 146);
    sids
}

/// Standard strings that give a name to a code in StandardEncoding: the SID of each code, 0 where none.
pub fn standard_encoding_sids() -> &'static [usize; 256] {
    static SIDS: std::sync::OnceLock<[usize; 256]> = std::sync::OnceLock::new();
    SIDS.get_or_init(standard_sids)
}

/// StandardEncoding as the name of each code, none where the code is unassigned.
pub fn standard_encoding(code: usize) -> Option<&'static str> {
    let sid = standard_encoding_sids()[code];
    (sid != 0).then(|| cff_strings()[sid])
}
